WITH base AS (SELECT *, temp_c - humidity AS temp_c_minus_humidity FROM device_readings WHERE firmware IN ('2.0.1', '1.1.0', '1.0.3')), flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '45' MINUTE THEN 1 ELSE 0 END AS is_new_burst FROM base), sessions_device_readings AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, CORR(temp_c, status_bits) AS corr_temp_c_status_bits, SUM(CASE WHEN device_code = 'DV-04' THEN temp_c_minus_humidity ELSE 0 END) AS dv_04_temp_c_minus_humidity, COUNT_IF(device_code = 'DV-01') AS dv_01_events FROM sessions_device_readings GROUP BY 1 ORDER BY hour_window DESC NULLS FIRST
